-- Easy Beans (business 1): Brasil Fazenda Boa Vista's photo becomes its own 2 kg bag, the one the café
-- buys, from its page on Puchero's shop (somospuchero.com/producto/brasil-fazenda-boa-vista-natural-espresso/),
-- cut to a bag's shape (4:5) and made small as the app does with photos. It replaces only the stand-in
-- the `coffee_links` migration put there (a Puchero bag labelled Burundi Gatara, recognised by its md5),
-- or no photo at all, so a photo the café has added since stays. Easy Beans is business 1 when it's named
-- so or Aron is on its team; anywhere else nothing changes, and running it again changes nothing.
do $$
begin
  if not exists (select 1 from public.business b
                  where b.id = 1
                    and (b.name ~* 'easy\s*beans'
                         or exists (select 1 from public.profiles p where p.business_id = 1 and p.full_name ~* '^\s*aron\M'))) then
    return;
  end if;
  -- Named, so the rules see Easy Beans (a migration runs signed out).
  perform set_config('app.business_id', '1', true);
  update public.coffees
     set photo = 'data:image/jpeg;base64,'
   where business_id = 1 and name ~* 'boa\s*vista'
     and (photo is null or md5(photo) = '07d34d81283a032aa8c8186578c216f8');
  perform set_config('app.business_id', '', true);
end $$;
